INSERT INTO symptoms (symptom_name,description,specialties,related_symptoms,urgency_score,possible_diseases,additional_info) VALUES
('Chest pain with abdominal pain','Pain or discomfort occurring simultaneously in the chest and abdomen.',ARRAY['Cardiology','Emergency Medicine','Gastroenterology'],ARRAY['Shortness of breath','Nausea','Vomiting','Sweating','Dizziness'],95,ARRAY['Myocardial infarction','Aortic dissection','Pulmonary embolism','Pancreatitis','Peptic ulcer disease','Gastroesophageal reflux disease'],'The combination can occur with both cardiac and gastrointestinal conditions. Chest pain with severe abdominal pain requires urgent assessment because serious cardiovascular and abdominal emergencies can overlap.'),
('Chest pain with shortness of breath','Chest discomfort occurring together with difficulty breathing or an inability to get enough air.',ARRAY['Cardiology','Pulmonology','Emergency Medicine'],ARRAY['Sweating','Nausea','Dizziness','Palpitations','Fainting'],98,ARRAY['Myocardial infarction','Pulmonary embolism','Pneumothorax','Heart failure','Pneumonia','Pericarditis'], 'Sudden or severe chest pain with shortness of breath is a potentially life-threatening combination and requires emergency assessment.'),
('Chest pain with nausea','Chest discomfort occurring together with nausea or an urge to vomit.',ARRAY['Cardiology','Emergency Medicine','Gastroenterology'],ARRAY['Sweating','Dizziness','Shortness of breath','Vomiting'],90,ARRAY['Myocardial infarction','Gastroesophageal reflux disease','Peptic ulcer disease','Pancreatitis','Panic attack'],'Nausea accompanying new chest pain can occur during myocardial infarction and should not automatically be attributed to a gastrointestinal cause.'),
('Chest pain with sweating','Chest discomfort accompanied by unusual sweating, particularly cold or clammy sweating.',ARRAY['Cardiology','Emergency Medicine'],ARRAY['Nausea','Shortness of breath','Dizziness','Weakness','Palpitations'],95,ARRAY['Myocardial infarction','Acute coronary syndrome','Angina','Panic attack','Pulmonary embolism'],'Chest pain with cold sweating is a concerning cardiovascular symptom combination and warrants urgent evaluation.'),
('Chest pain with dizziness','Chest discomfort accompanied by lightheadedness, imbalance, or a sensation of impending fainting.',ARRAY['Cardiology','Emergency Medicine','Neurology'],ARRAY['Fainting','Shortness of breath','Palpitations','Nausea','Weakness'],92,ARRAY['Myocardial infarction','Cardiac arrhythmia','Pulmonary embolism','Aortic stenosis','Panic attack'],'Chest pain with dizziness may indicate impaired cardiac output or another serious condition, particularly if symptoms are sudden or severe.'),
('Chest pain with fainting','Chest discomfort occurring with temporary loss of consciousness.',ARRAY['Cardiology','Emergency Medicine'],ARRAY['Palpitations','Shortness of breath','Dizziness','Weakness'],98,ARRAY['Cardiac arrhythmia','Myocardial infarction','Aortic stenosis','Pulmonary embolism','Aortic dissection'],'Syncope associated with chest pain can indicate a serious cardiac or vascular condition and requires emergency assessment.'),
('Chest pain with palpitations','Chest discomfort accompanied by awareness of rapid, pounding, fluttering, or irregular heartbeats.',ARRAY['Cardiology','Emergency Medicine'],ARRAY['Dizziness','Fainting','Shortness of breath','Sweating'],90,ARRAY['Cardiac arrhythmia','Atrial fibrillation','Supraventricular tachycardia','Myocardial infarction','Hyperthyroidism','Panic attack'],'Urgency increases substantially when palpitations are sustained or accompanied by fainting, severe breathlessness, or significant chest pain.'),
('Chest pain with fever','Chest discomfort occurring together with elevated body temperature.',ARRAY['Cardiology','Pulmonology','Emergency Medicine','Infectious Disease'],ARRAY['Cough','Shortness of breath','Chills','Sputum production'],75,ARRAY['Pneumonia','Pericarditis','Myocarditis','Pulmonary infection','Pleurisy'],'Chest pain with fever can indicate an infectious or inflammatory process, especially when accompanied by cough or breathing difficulty.'),
('Chest pain with coughing blood','Chest pain occurring together with expectoration of blood from the respiratory tract.',ARRAY['Pulmonology','Emergency Medicine','Cardiology'],ARRAY['Shortness of breath','Cough','Dizziness','Rapid heartbeat'],98,ARRAY['Pulmonary embolism','Pneumonia','Tuberculosis','Lung cancer','Bronchiectasis'],'Chest pain combined with haemoptysis can indicate pulmonary embolism or another significant pulmonary condition and requires urgent evaluation.'),
('Chest pain with arm pain','Chest discomfort accompanied by pain or discomfort extending into one or both arms.',ARRAY['Cardiology','Emergency Medicine'],ARRAY['Jaw pain','Neck pain','Sweating','Nausea','Shortness of breath'],98,ARRAY['Myocardial infarction','Acute coronary syndrome','Angina','Aortic dissection','Cervical radiculopathy'],'Chest pain radiating to an arm is a classic warning pattern for acute coronary syndrome, particularly when accompanied by breathlessness, sweating or nausea.'),
('Chest pain with jaw pain','Chest discomfort accompanied by pain or discomfort in the jaw.',ARRAY['Cardiology','Emergency Medicine','Dentistry'],ARRAY['Arm pain','Neck pain','Sweating','Nausea','Shortness of breath'],98,ARRAY['Myocardial infarction','Acute coronary syndrome','Angina','Temporomandibular disorder','Dental disease'],'New chest pain with jaw discomfort should be treated as potentially cardiac until serious causes have been excluded.'),
('Abdominal pain with vomiting','Abdominal pain occurring together with repeated or persistent vomiting.',ARRAY['Gastroenterology','General Surgery','Emergency Medicine'],ARRAY['Nausea','Fever','Abdominal swelling','Dehydration'],75,ARRAY['Gastroenteritis','Appendicitis','Pancreatitis','Bowel obstruction','Cholecystitis','Food poisoning'],'Severe abdominal pain with persistent vomiting can indicate an acute abdominal emergency, especially when there is distension, fever, or inability to pass stool or gas.'),
('Abdominal pain with fever','Abdominal discomfort accompanied by elevated body temperature.',ARRAY['Gastroenterology','General Surgery','Emergency Medicine'],ARRAY['Nausea','Vomiting','Chills','Abdominal tenderness'],80,ARRAY['Appendicitis','Cholecystitis','Diverticulitis','Pancreatitis','Gastroenteritis','Intra-abdominal infection'],'Abdominal pain with fever raises concern for infection or inflammation and requires prompt evaluation when severe or progressive.'),
('Abdominal pain with diarrhoea','Abdominal discomfort or cramping occurring with frequent loose or watery stools.',ARRAY['Gastroenterology','General Medicine','Infectious Disease'],ARRAY['Nausea','Vomiting','Fever','Dehydration'],55,ARRAY['Gastroenteritis','Food poisoning','Inflammatory bowel disease','Irritable bowel syndrome','Antibiotic-associated diarrhoea'],'The combination is commonly caused by gastrointestinal infection, but blood in stool, severe pain, dehydration, or persistent symptoms increase urgency.'),
('Abdominal pain with blood in stool','Abdominal pain occurring together with visible blood or bloody stools.',ARRAY['Gastroenterology','Emergency Medicine','General Surgery'],ARRAY['Diarrhoea','Dizziness','Weakness','Fever','Vomiting'],90,ARRAY['Gastrointestinal bleeding','Inflammatory bowel disease','Diverticulitis','Ischaemic colitis','Colorectal cancer','Infectious colitis'],'Abdominal pain with gastrointestinal bleeding can represent significant intestinal inflammation, ischaemia, or haemorrhage and requires urgent assessment.'),
('Abdominal pain with blood in urine','Abdominal or flank pain occurring together with visible blood in urine.',ARRAY['Urology','Nephrology','Emergency Medicine'],ARRAY['Flank pain','Painful urination','Nausea','Vomiting'],80,ARRAY['Kidney stone','Urinary tract infection','Kidney disease','Bladder disease','Kidney cancer'],'The combination commonly occurs with urinary tract pathology. Severe flank pain with vomiting or urinary obstruction requires urgent assessment.'),
('Abdominal pain with jaundice','Abdominal discomfort occurring together with yellowing of the skin or whites of the eyes.',ARRAY['Gastroenterology','Hepatology','Emergency Medicine'],ARRAY['Nausea','Vomiting','Dark urine','Pale stools','Fever'],85,ARRAY['Cholecystitis','Cholangitis','Gallstones','Hepatitis','Pancreatitis','Liver disease'],'Abdominal pain with jaundice and fever can indicate biliary infection and requires urgent assessment.'),
('Shortness of breath with fever','Difficulty breathing occurring together with an elevated body temperature.',ARRAY['Pulmonology','Emergency Medicine','Infectious Disease'],ARRAY['Cough','Chills','Sputum production','Chest pain','Fatigue'],80,ARRAY['Pneumonia','Influenza','COVID-19','Bronchitis','Sepsis','Asthma exacerbation'],'Breathlessness with fever may indicate a respiratory infection. Severe breathing difficulty, cyanosis, confusion, or rapid deterioration requires emergency care.'),
('Shortness of breath with leg swelling','Difficulty breathing occurring together with swelling of one or both legs.',ARRAY['Cardiology','Pulmonology','Vascular Medicine','Emergency Medicine'],ARRAY['Chest pain','Leg pain','Rapid heartbeat','Weight gain'],95,ARRAY['Pulmonary embolism','Deep vein thrombosis','Heart failure','Chronic venous insufficiency','Kidney disease'],'Sudden breathlessness with unilateral leg swelling can indicate deep vein thrombosis with pulmonary embolism and requires emergency assessment.'),
('Shortness of breath with fainting','Difficulty breathing occurring together with temporary loss of consciousness.',ARRAY['Cardiology','Pulmonology','Emergency Medicine'],ARRAY['Chest pain','Palpitations','Dizziness','Weakness'],99,ARRAY['Pulmonary embolism','Cardiac arrhythmia','Myocardial infarction','Aortic stenosis','Severe hypoxia'],'Breathlessness accompanied by fainting is a high-risk combination and requires emergency assessment.'),
('Shortness of breath with palpitations','Difficulty breathing occurring together with awareness of rapid or irregular heartbeats.',ARRAY['Cardiology','Pulmonology','Emergency Medicine'],ARRAY['Chest pain','Dizziness','Fainting','Sweating'],90,ARRAY['Cardiac arrhythmia','Heart failure','Atrial fibrillation','Supraventricular tachycardia','Hyperthyroidism','Panic attack'],'The combination can result from cardiovascular or respiratory disease. Fainting or significant chest pain increases urgency.'),
('Fever with confusion','Elevated body temperature occurring with an acute change in awareness, orientation, attention, or thinking.',ARRAY['Emergency Medicine','Infectious Disease','Neurology'],ARRAY['Weakness','Headache','Neck stiffness','Dizziness','Reduced consciousness'],95,ARRAY['Sepsis','Meningitis','Encephalitis','Severe infection','Electrolyte disturbance'],'Fever with acute confusion can indicate severe infection or central nervous system disease and requires urgent emergency assessment.'),
('Fever with stiff neck','Fever occurring together with marked neck stiffness or difficulty flexing the neck.',ARRAY['Neurology','Infectious Disease','Emergency Medicine'],ARRAY['Severe headache','Photophobia','Vomiting','Confusion'],98,ARRAY['Meningitis','Encephalitis','Subarachnoid haemorrhage','Severe systemic infection'],'Fever with severe headache and neck stiffness is a classic emergency warning pattern for meningitis and other serious neurological conditions.'),
('Severe headache with vomiting','Intense headache occurring together with repeated or significant vomiting.',ARRAY['Neurology','Emergency Medicine'],ARRAY['Photophobia','Neck stiffness','Visual changes','Confusion','Dizziness'],85,ARRAY['Migraine','Intracranial haemorrhage','Raised intracranial pressure','Meningitis','Brain tumour'],'Severe or sudden headache accompanied by vomiting, neurological deficits, confusion, or neck stiffness requires urgent evaluation.'),
('Headache with vision changes','Headache occurring together with blurred vision, double vision, visual loss, flashes, or other new visual abnormalities.',ARRAY['Neurology','Ophthalmology','Emergency Medicine'],ARRAY['Dizziness','Nausea','Eye pain','Weakness'],85,ARRAY['Migraine with aura','Glaucoma','Stroke','Transient ischaemic attack','Raised intracranial pressure','Optic neuritis'],'Sudden visual loss or headache with neurological deficits requires emergency assessment.'),
('Weakness with numbness','Reduced strength occurring together with reduced sensation or abnormal sensation in one or more body regions.',ARRAY['Neurology','Emergency Medicine'],ARRAY['Dizziness','Speech difficulty','Facial drooping','Vision changes','Balance problems'],90,ARRAY['Stroke','Transient ischaemic attack','Peripheral neuropathy','Multiple sclerosis','Nerve compression'],'Sudden weakness and numbness, particularly on one side of the body, is a major stroke warning pattern and requires emergency assessment.'),
('Weakness with speech difficulty','Reduced muscle strength or control occurring together with difficulty speaking, finding words, or understanding speech.',ARRAY['Neurology','Emergency Medicine'],ARRAY['Facial drooping','Numbness','Dizziness','Vision changes','Confusion'],99,ARRAY['Stroke','Transient ischaemic attack','Intracranial haemorrhage','Seizure'],'Sudden weakness with speech difficulty should be treated as a possible stroke and requires immediate emergency assessment.'),
('Dizziness with fainting','Lightheadedness or a sensation of impending loss of consciousness occurring together with actual temporary loss of consciousness.',ARRAY['Cardiology','Neurology','Emergency Medicine'],ARRAY['Palpitations','Chest pain','Weakness','Shortness of breath'],90,ARRAY['Cardiac arrhythmia','Vasovagal syncope','Orthostatic hypotension','Structural heart disease','Hypoglycaemia'],'Repeated or unexplained fainting, particularly with chest pain or palpitations, requires medical assessment.'),
('Nausea with sweating','Nausea occurring together with unusual sweating, particularly cold or clammy sweating.',ARRAY['Cardiology','Emergency Medicine','Gastroenterology'],ARRAY['Chest pain','Dizziness','Weakness','Shortness of breath'],80,ARRAY['Myocardial infarction','Gastroenteritis','Hypoglycaemia','Panic attack','Heat-related illness'],'Nausea and sweating are nonspecific but become concerning when accompanied by chest discomfort, breathlessness, dizziness, or weakness.'),
('Vomiting with dizziness','Repeated vomiting occurring together with dizziness or lightheadedness.',ARRAY['Gastroenterology','General Medicine','Emergency Medicine'],ARRAY['Nausea','Dehydration','Weakness','Abdominal pain','Headache'],65,ARRAY['Gastroenteritis','Dehydration','Migraine','Food poisoning','Vestibular disorder','Electrolyte disturbance'],'Persistent vomiting can cause dehydration and electrolyte abnormalities, which can worsen dizziness and weakness.');